CREATE SCHEMA verde2;
SET LOCAL search_path=verde2,public;
CREATE TABLE migration_history(version text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE schema_identity(id boolean PRIMARY KEY DEFAULT true CHECK(id), fingerprint text NOT NULL);
CREATE TABLE control(id boolean PRIMARY KEY DEFAULT true CHECK(id), dispatch_enabled boolean NOT NULL DEFAULT false, service_daily integer NOT NULL DEFAULT 2000 CHECK(service_daily>0));
INSERT INTO control DEFAULT VALUES;
CREATE TABLE tenants(id uuid PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, application text NOT NULL, environment text NOT NULL, active boolean NOT NULL DEFAULT true, per_minute integer NOT NULL DEFAULT 60 CHECK(per_minute>0), per_day integer NOT NULL DEFAULT 1000 CHECK(per_day>0), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(application,environment));
CREATE TABLE credentials(id uuid PRIMARY KEY, tenant_id uuid REFERENCES tenants(id), kind text NOT NULL CHECK(kind IN ('admin','http','smtp')), purpose text CHECK(purpose IN ('keycloak','worker')), username text UNIQUE, secret_hash text NOT NULL UNIQUE, secret_cipher text, scopes text[] NOT NULL DEFAULT '{}', expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(tenant_id,id), CHECK ((kind='admin' AND tenant_id IS NULL AND purpose IS NULL) OR (kind='http' AND tenant_id IS NOT NULL AND purpose IS NULL) OR (kind='smtp' AND tenant_id IS NOT NULL AND purpose IS NOT NULL AND username IS NOT NULL)));
CREATE TABLE senders(tenant_id uuid NOT NULL REFERENCES tenants(id), address text NOT NULL, reply_to boolean NOT NULL DEFAULT false, PRIMARY KEY(tenant_id,address));
CREATE TABLE templates(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), slug text NOT NULL, definition_cipher text NOT NULL, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,slug));
CREATE TABLE messages(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), credential_id uuid NOT NULL, template_id uuid, source text NOT NULL CHECK(source IN ('http','smtp')), state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','in_flight','accepted_local','deferred','accepted_remote','failed_permanent','rejected_submission','expired','outcome_unknown')), content_cipher text, content_hash text NOT NULL, recipient_hash text NOT NULL, message_id text NOT NULL UNIQUE, envelope_from text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '23 hours 50 minutes', terminal_at timestamptz, lease_id uuid, lease_until timestamptz, submission_started_at timestamptz, queue_id text, instance_id text, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,credential_id) REFERENCES credentials(tenant_id,id), FOREIGN KEY(tenant_id,template_id) REFERENCES templates(tenant_id,id));
CREATE UNIQUE INDEX messages_queue ON messages(instance_id,queue_id) WHERE queue_id IS NOT NULL;
CREATE TABLE idempotency(tenant_id uuid NOT NULL REFERENCES tenants(id), key_hash text NOT NULL, request_hash text NOT NULL, message_id uuid NOT NULL, expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '30 days', PRIMARY KEY(tenant_id,key_hash), FOREIGN KEY(tenant_id,message_id) REFERENCES messages(tenant_id,id));
CREATE TABLE reservations(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), message_id uuid NOT NULL UNIQUE, state text NOT NULL DEFAULT 'held' CHECK(state IN ('held','consumed','released','uncertain')), lease_id uuid, binding_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(tenant_id,message_id) REFERENCES messages(tenant_id,id));
CREATE TABLE outbox(message_id uuid PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE, available_at timestamptz NOT NULL DEFAULT clock_timestamp(), published_at timestamptz);
CREATE TABLE attempts(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, message_id uuid NOT NULL, smtp_credential_id uuid NOT NULL, lease_id uuid NOT NULL UNIQUE, started_at timestamptz NOT NULL DEFAULT clock_timestamp(), finished_at timestamptz, outcome text, FOREIGN KEY(tenant_id,message_id) REFERENCES messages(tenant_id,id), FOREIGN KEY(tenant_id,smtp_credential_id) REFERENCES credentials(tenant_id,id));
CREATE TABLE events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, event_key text NOT NULL UNIQUE, tenant_id uuid NOT NULL, message_id uuid NOT NULL, type text NOT NULL, enhanced_status text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(tenant_id,message_id) REFERENCES messages(tenant_id,id));
CREATE TABLE suppressions(tenant_id uuid NOT NULL REFERENCES tenants(id), recipient_hash text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,recipient_hash));
CREATE TABLE audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid, action text NOT NULL, resource_id uuid, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE smtp_connections(id uuid PRIMARY KEY, credential_id uuid REFERENCES credentials(id), expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes');
CREATE INDEX reservations_quota ON reservations(created_at,tenant_id) WHERE state <> 'released';
CREATE INDEX messages_dispatch ON messages(state,expires_at);
CREATE INDEX events_tenant ON events(tenant_id,created_at);
